INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1050456-mis215', 'stk-fol12', 'MIS 215', 'info', '{"desc": "البعض يعتبرها مادة قريد والبعض يعتبرها مادة “مزعجة جدا”. الفرق بين الاثنين بسيط ان اللي يعتبرها مادة قريد يقدر يستوعب الكلام السرد ويفهمه بينما اللي يعتبرها مادة مزعجة يعتمد عالحفظ و حفظه ضعيف.\nالمادة من ناحية الاستفادة مفيدة بشكل عام في مجال الآي تي.\nراح تقرا مصطلحات جديدة و تعرف اهمية النظم في الشركات وأهمية الشبكات أيضا. المادة بشكل عام نظرية وتعتمد على فهمك أولا بعدين على الحفظ. بمعنى ان حفظك بلا فهم ما راح يفيدك.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mis-215-principles-of-management-information-systems/120972/5", "user": "fol12", "ts": 1338791452000, "tid": 120972, "pn": 5}}', 1338791452000, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1422189-mis215', 'stk-user10207', 'MIS 215', 'info', '{"desc": "MIS 215 – Term 141\nالمادة هي عبارة عن مقدمة بسيطة عن مبادئ نظم المعلومات من ناحية إدارية.\n\nChapter 1: The information age in which you live: Changing the face of business\nمقدمة عن نظم المعلومات الإدارية. نموذج القوى التنافسية الخمسة لمايكل بورتر. إستراتيجيات مايكل بورتر الثلاثة العامة. تحليل سلسلة القيمة. النموذج والإستراتيجيات مهمة لأنها عليها\nهومورك وكتابة ريبورت. يعتبر أهم شبتر في الكتاب.\n\nChapter 3: Database and data warehouses: Building business intelligence\nيتحدث عن قواعد البيانات العلائقية، وأدوات نظام إدارة قواعد البيانات، ومستودع البيانات والتنقيب عن البيانات، وذكاء الأعمال، وملكية المعلومات.\n\nModule C: Designing Database and Entity-Relationship Diagramming\nتصميم وبناء قاعدة بيانات علائقية. الشبتر هذا فيه رسمات كثير توضح كيف تصمم قاعدة بيانات. مهم جداً عشان تفهم شبتر 3 و module J أكثر.\n\nModule J: Implementing a Database with Microsoft Access\nالأشياء في هذا الشبتر هي اساسيات في قواعد البيانات. يعتبر أطول شبتر ويتكلم عن كيفية تنفيذ قاعدة بيانات مع برنامج مايكروسوفت أكسس.\nيبدأ معك الشبتر في مثال لشركة وتسويلها entity class و primary key، وبعد ذلك تعمل العلاقات بين الجداول، وتكتب العمود والبيانات عنه وبعدها تكتب المعلومات بالجداول هذه.\nعلى نهاية الشبتر فيه تطبيقات على قواعد البيانات، عمل ريبورت مع التجميع والفرز، شكل إدخال بيانات، عمل سؤال (query)، وغيرها.\nالشبتر هذا يمكن يكون عليه لاب لأن فيه شغل عملي، بس ماعليه درجات.\n\nChapter 2: Major business initiatives: Gaining competitive advantages with IT\nإدارة سلسلة الإمدادات، إدارة علاقات العملاء، التعاون الإلكتروني، it culture، تخطيط موارد المؤسسة.\nالشبتر هذا مهم. عليه هومورك.\n\nChapter 5: Electronic commerce: Strategies for the new economy\nيتحدث الشبتر عن التجارة الإلكترونية والنماذج التسعة للتجارة الإلكترونية. كيفية تحويل النقود عبر الإنترنت بشكل آمن. إيجاد عملاء وعمل علاقات جيدة معهم. كيف تفهم عملائك. كيف\nتبيع الشركات لشركات ثانية غير لما تبيع لأشخاص. إتجاه الأعمال الإلكترونية.\n\nChapter 6: Systems development: Phases, tools, and techniques\nشبتر مهم. يتكلم عن تطوير الأنظمة والمراحل والأدوات والتقنيات المستخدمة. الشبتر بيتكلم عن المراحل الـ سبعة الي هي: التخطيط، التحليل، التصميم، التطوير، الإختبار، التنفيذ، الصيانة.\nكيفية النمذجة وعمل النماذج. كيفية بناء IT systems تبع الشركة عن طريق 3 خيارات.\n\nChapter 7: Enterprise infrastructure, metrics, and business continuity planning: building and sustaining the dynamic enterprise\nيتكلم عن تخطيط موارد المؤسسسات ERP، الأشياء الي تحتاجها الشركة، المنظمة وغيرها من المعلومات والهاردوير والسوفروير وغيرها. السحابة الإلكترونية. كيفية إستمرار الشركة إذا\nصارت مشاكل مثل الزلازل وغيرها. إستمرارية الشركة. كيف تقيم أداء المواقع الإلكترونية، كيف تقيم المكالمات تبع الشركة (call center) وأشياء ثانية كثير.\n\nChapter 8: Protecting people and information: Threats and safeguard\nشبتر طويل يتكلم عن الأخلاق، الخصوصية، الحماية، السرقة، انتحال الشخصية، الفيروسات، كيفية حماية معلوماتك، جرائم الإنترنت، الهاكرز، وأشياء كثير.\n\nChapter 9: Emerging trends and technologies: Business, people, and technology\nيتكلم هذا الشبتر عن التقنيات القديمة، والجديدة الي ظهرت مؤخراً في عالم التقنية. يوجد 21 مثال في الشبتر.\n\nالكتاب إسمه Management Information Systems for the Information Age\nللمؤلفين Stephen Haag & Maeve Cummings\nالكتاب جيد، لكن كلامه كثير. فيه أيضاً ملخص بنهاية الشبتر مهم.\n\nماتيريال الميجر الأول: Chapters 1 + 3 + Module C + Module J\nماتيريال الميجر الثاني: Chapters 2 + 5 + 6\nماتيريال الفاينل: Chapters 7 + 8 + 9 فقط (ليس كومبرهنسف)\n\nتوزيع الدرجات\nالميجر الأول 20%\nالميجر الثاني 20%\nالفاينل 20%\nبروجكت 15% وعليه report و presentation\nكويزات 10%\nكلاس وورك 10%\nحالة دراسية Case study 5%\n\nالمياجر والفاينل نفس الشيء. ثلاثين فقرة إختيارات وثلاثة أسئلة كتابية، من كل شبتر سؤال.\nبالنسبة للقريدات. الـ A+ من 90.\nالـ DN يجي من الغياب السادس بدون عذر.\n\nنصائح للمادة:\n\n- ذاكر من الكتاب وليس من السلايدات. السلايدات ماتصلح للمذاكرة لأنها مختصرة.\n\n- لم أستخدم الـ TB في المذاكرة ولكن أعتقد لن ينفع في هذا الكورس. الإختبارات فيها اسئلة كثير مسويها الديبارتمنت، أيضاً فيه اسئلة مقالية تحتاج فهم ومذاكرة من الكتاب.\n\n- حاول تسوي البروجكت من بدري لأنك يمكن تنضغط في النهاية.\n\n- لا تحاول تغيب. إذا غبت بيروح عليك البونص. وإحتمال يكون فيه كلاس وورك في اليوم الي غبته مثل الي كان يعطينا إياها المدرس الي أخذته معه المادة.\n\n- حاول تقرأ الكتاب أول بأول، لأنه مع ضغط المياجر والفاينلات لكورسات ثانية بتتعب في القراءة والفهم.\n\n- عشان تحصل على درجات عالية، ممنوع تنقل الهوموركات أو أي assignment أو بروجكت من طالب ثاني لأن المدرسين عندهم المعلومات عن جميع السكاشن.\n\n- أنتبه للـ value chain analysis لأنه عليه لحاله 5%. هو مثل الهومورك البسيط عن موضوع يختاره المدرس. حاول تبدع بهذا الهومورك وبطريقة كتابة الريبورت.\n\n- المادة مهمة! لأن فيها 3 شباتر عن قواعد البيانات و data modeling والي راح تدرسها بالتفصيل سواء كان تخصصك محاسبة (ACCT 300 فيها كم شبتر عن هذا الشيء وحاجات ثانية بالـ MIS) أو تخصصك نظم معلومات إدارية لأن فيها كورس كامل عن هذا الشيء، أو حتى تسويق أو فاينانس أو ادارة لأنه بتستخدم هذه الأشياء بالكوأب وبالوظيفة وربما بكورسات.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mis-215-principles-of-management-information-systems/120972/7", "user": "user10207", "ts": 1422219113000, "tid": 120972, "pn": 7}}', 1422219113000, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1440423-mis215', 'stk-azooz_jk', 'MIS 215', 'info', '{"desc": "جودة المقرر بشكل عام\nكويس وحلو تقني بشكل كبيير مليان مصطلحات الي يقرا مرتين يفهم الموضوع\n\nالمواضيع التي يغطيها المقرر\nالاخوان كتبو\n\nالكتاب المستخدم للمقرر\nمررة كويس\nالأسئلة والأمثلة المستخدمة في المقرر\nتي بي بس تقدر تقول ثلث الاختبار مو منو\n\nمدى فائدته في الناحية التطبيقية\nيب حلو وممتع مادة قريد اذا اديتها حقها", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mis-215-principles-of-management-information-systems/120972/8", "user": "Azooz_Jk", "ts": 1453652087000, "tid": 120972, "pn": 8}}', 1453652087000, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1474319-mis215', 'stk-maxmx05', 'MIS 215', 'info', '{"desc": "TERM - 162\n\nليش ذكرت الترم ؟ لان هذي المادة فريدة من نوعها كل كم سمستر يتيغير الكتاب لان التكنزلوجيا تتطور\n\nجودة المقرر بشكل عام : ممتازة جدا , يعطيك نبذة بسيطة و مختصرة عن التجارة الاكترونية بشكل عام\n\nالمواضيع التي يغطيها المقرر : 8 شباتر , تبدا بتعريف مبسط و مبدائي عن نظم المعلومات الادارية ثم تنتقل بشكل بسيط وسلس الى مواضعات بسيطة اخرى\n\nالكتاب المستخدم للمقرر : ممتاز بشكل عام , ممتع نوعا ما اذا جيت تقراه كانه جريدة\n\nالأسئلة والأمثلة المستخدمة في المقرر: مافي مسائل في هذي المادة , المادة 95% منها نظرية\n\nاضافات\n\nاذا تبي تطلع من الكورس ب قريد حلو وهو سهل نوعا ما , لكن بعطيك نصايح تسهل عليك عملية المذاكرة راح تخصتر عليك الوقت\n\n1- ذاكر التعريفات الملونة بلون اسود غامق ( BLOD ) اذا ذاكرتها بس هي اضمن لك 8 وفوق في الكويز و 17 وفوق في الميجر من 20\n\n2- اذا عندك وقت مر بفهم على محتويات الكتاب عشان تاخذ فكرة موسعة عنها\n\n* تذكر ان كل مادة لها طريقة في المذاكرة هذي تعتمد الى حد كبييييييير الى الحقظ فا هالله هالله في الكلمات الملونة بالسود عشان انت مش راح يكون عندك بس MIS فخلصها ورح ذاكر الباقي", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mis-215-principles-of-management-information-systems/120972/9", "user": "Maxmx05", "ts": 1496338112000, "tid": 120972, "pn": 9}}', 1496338112000, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1507354-mis215', 'stk-kbsc', 'MIS 215', 'info', '{"desc": "جودة المقرر بشكل عام\n\nجيد جدا\n\n- المواضيع التي يغطيها المقرر\n\nمقدمة في نظم المعلومات الادارية فيها عدة مواضيع مفيدة في التكنولوجيا والبزنس\n\n- الكتاب المستخدم للمقرر\n\nجيد بس ما استفدت منه\n\n- طريقة مذاكرة المقرر\n\nTB + سلايدات", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mis-215-principles-of-management-information-systems/120972/10", "user": "KBSC", "ts": 1552816021000, "tid": 120972, "pn": 10}}', 1552816021000, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-kbsc-mis215', 'stk-kbsc', 'MIS 215', 'doc', '{"docs": [{"id": "stk-dr-f98414", "n": "Dr. Ibrahim M. Al-Jabri", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "اسم الدكتور : *\n\nIbrahim Al-Jabri\n\nالمادة: *\n\nMis-215\n\nطريقة الشرح : *\n\nسلايدات خاصة بالدكتور\n\nالكويزات :\n\nذاكر السلايدات تضمن درجة حلوة بكويزاته\n\nالمياجر/ميد:\n\nكومن\nالفاينل :\n\nكومن\n\nطريقة التحضير :\n\nورقة تحضير،مايهتم للتاخير، الا اذا تاخرت كثير احيان يحرجك.\nالقريد النهائي الخاص بك :\n\nA\nاضافات:\n\nمافي بونص،لاتهمل الكويزات سهله بس ذاكر سلايداته قبلها ولاتضيع الكلاس وورك. الباقي سهالات", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1507360-mis215", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-ibrahim-m-al-jabri/98414/5", "user": "KBSC", "ts": 1552816868000, "tid": 98414, "pn": 5}}]}', 1552816868000, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-sadguts-mis215', 'stk-sadguts', 'MIS 215', 'doc', '{"docs": [{"id": "stk-dr-f98414", "n": "Dr. Ibrahim M. Al-Jabri", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Mis215-201\nالتحضير: bb\nالشرح: الدكتور ابراهيم اسطوره لايعلى عليه شرحه ممتاز وكلاسه ممتع من امتع مايكون من افضل الدكاتره الي درست عندهم والماده جميله\nالكويزات: سهله ل متوسطه يحط كم سؤال فيه تركات لازم تكون فاهم و/او مذاكر الكتاب، والكتاب عموما طريقك للA+\nاضافات: دكتور اسطوره نزل عنده اذا قدرت ومابتندم", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1527856-mis215", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-ibrahim-m-al-jabri/98414/6", "user": "SadGuts", "ts": 1610563780000, "tid": 98414, "pn": 6}}]}', 1610563780000, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mlekon-mis215', 'stk-mlekon', 'MIS 215', 'doc', '{"docs": [{"id": "stk-dr-f98440", "n": "Dr. Mustafa Faisal Ahmed", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "التحضير :\nيحضر بداية السمستر بعدين يسحب على التحضير\n\nطريقة الشرح :\nالشرح مب ذاك الزود غالبا يقعد يسولف عن الموضوع ما يمشي على منهج معين وبعدين قبل الاختبار باسبوع او ثنين يفتح السلايدات ويشرح منها على السريع\n\nالكويزات :\nكويز ولا كويزين طول السمستر وتكون MCQ من التي بي.\n\nالمياجر:\nفي mis215 كومن.\nفي mis300 يعطيك الأشياء اللي تذاكرها وغالبا ما تطلع من اللي يحدده لك. وبالنسبة للـMCQ اللي هي نص الى ثلث الاختبار فتكون من الـTB.\n\nغالبا قبل الميجر يقول لك وش تركز عليه ويجيبه في الميجر\n\nالفاينلات :\nنفس طريقة المياجر.\n\nالقريد النهائي:\nA+\n\nالصوت:\nعالي وواضح.\nواللغة ممتازة ومفهومه\n\nإضافات :\nالمدرس ممتاز كتعامل وما يقصر في القريدات لكن مشكلته مب مرتب يضيعك شوي معه لكن ما يقصر معك في القريد نهاية السمستر", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1529310-mis215", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mr-ahmed-mustafa-faisal/98440/5", "user": "MLEKON", "ts": 1617431805000, "tid": 98440, "pn": 5}}, {"id": "stk-dr-f98414", "n": "Dr. Ibrahim M. Al-Jabri", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "اسم الدكتور : *\n\nIbrahim Al-Jabri\n\nالمادة: *\n\nMis-215\n\nطريقة الشرح : *\n\nسلايدات خاصة بالدكتور وشرحة ممتاز ويعطي أمثلة جميلة وما عنده مشكلة يعيد الشرح اذا فيه احم ما فهم\n\nالكويزات :\n\nمتوسطة اذا انت فاهم الموضوع بتمشي\n\nالمياجر/ميد:\n\nكومن\nالفاينل :\n\nكومن\n\nطريقة التحضير :\n\nورقة تكتب فيها اسمك وما يدقق مره على التحضير.\nيسمح للطلاب يحضرون في غير سكاشنهم فمثلا اذا كان سكشنك الساعة 10 ما عنده مشكلة تحضر في سككشن لساعة 8 او 9 لكن لازم تختار سكن تحضر فيه طول السمستر\nالقريد النهائي الخاص بك :\nnp (كورونا)", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1529311-mis215", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-ibrahim-m-al-jabri/98414/7", "user": "MLEKON", "ts": 1617432149000, "tid": 98414, "pn": 7}}]}', 1617431805000, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user12089-mis215', 'stk-user12089', 'MIS 215', 'doc', '{"docs": [{"id": "stk-dr-f98414", "n": "Dr. Ibrahim M. Al-Jabri", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ترم 202 ( ترم الدراسة عن بعد )\n\nاسم الدكتور : *\n\nIbrahim Al-Jabri\n\nالمادة: *\n\nMIS-215\n\nطريقة الشرح : *\nسلايدات الكتاب مع بعض الاضافات من الدكتور مثل امثلة جميلة توضح المعنى, واذا ما احد فهم يعيد له الشرح مع اعطاء امثلة اكثر. ويحب يسمع من تجارب الطلاب ورايهم بالمواضيع الي يشرحها.\n\nالكويزات :\n\nمتوسطة الصعوبة وفيه كم سؤال فيهم خدع لازم تكون قريت الكتاب او مركز مع شرح الدكتور عشان تقدر تجاوبهم\n\nالمياجر/ميد:\n\nكومن\n\nالفاينل :\n\nكومن\n\nطريقة التحضير :\n\nما كان يحضر بالاونلاين\n\nالقريد النهائي:\nA\n\nاضافات:\nالدكتور ممتاز ومتساعد مع الطلاب دائما وكريم بنهاية الترم عمل اختبار تحسين درجة وعمل اختبار ثاني بونس, لو سمحت لي الفرصة مستعد اخذ معه كورس ثاني انصح فيه .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1530067-mis215", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-ibrahim-m-al-jabri/98414/8", "user": "user12089", "ts": 1621768093000, "tid": 98414, "pn": 8}}]}', 1621768093000, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-two-nine-mis215', 'stk-two-nine', 'MIS 215', 'doc', '{"docs": [{"id": "stk-dr-f98417", "n": "Dr. Ahmed S. Alojairi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "التحضير :يومي في بداية المحاضره\nطريقة الشرح :بإستخدام السلايدات ,ايضا دائما يوضح الدرس بأمثله حقيقيه نعيشها نحن\nالكويزات :متوسطه الى سهله\nالمياجر:كومن\nالفاينلات :كومن\nالقريد النهائي:a\n\nالصوت:,واضح\nإضافات :مايمر كلاس الى وهو يدخل تويتر بالسالفه\n_______________\nانا ماخذ معه mis215", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p942818-mis215", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-ahmed-s-alojairi/98417/7", "user": "TWO-NINE", "ts": 1323081836000, "tid": 98417, "pn": 7}}]}', 1323081836000, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-cortex-mis215', 'stk-cortex', 'MIS 215', 'doc', '{"docs": [{"id": "stk-dr-f98428", "n": "Dr. Hussam Almulhim", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "التحضير :\nما يحضّر بس يعرف الطلاب كويّس و ياخذ عن اللي يغيبون صورة سيئة صعب تتعدل . لكن ما يحظر ولا يخصم على الغياب. لكن أظن الغياب بالمعرفة و في النهاية ( قد ) تاخذ DN .\n\nطريقة الشرح :\nالشرح ممتع جداً . أخذت معه الترم ذا و كان الكلاس ساعة و ربع … و بصراحة كان أمتع كلاس في الترم كامل ( علماً إني منزل 18 ساعه ) مع إني أمقت الكلاسات الطويلة . الشرح عبارة عن سواليف , و أصلاً بتكون قاري التشابتر عشان الكويزات فبتكون جالس تتناقش في شي أنت فاهمة أصلاً و جالس تعطي رأيك فيه … فتتأصّل المعلومة .\n\nالكويزات :\n\nالكويزات على كل تشابتر كويز واحد . تذاكر للكويز ( قبل ) التشابتر و تختبر فيه بعدين تاخذ التشابتر و يكون نقاش عن طريق سلايدز . الكويزات تركز بنسبة كبيرة على عمق الفهم و كمية لا بأس بها من الحفظ … بس أنا كنت أذاكر ساعة للكويزات و أفهم المتيريال حقها و اخذ الكويزز … و أغلب كويزاتي 9 من 10 .\n\nالمياجر:\n\nالمياجر كومون … لكن أظن تصحيحه للرايتنق شديد حبّتين . يهمه الخط يكون كويس و يهمه ترتيب الكلام و لغة الكتابة … و ممكن جداً يعطيك بونص .\n\nالفاينلات :\n\nالفاينل كان كومون من 60 سؤال إختياري و الدرجة الكلية من 20 يعني السؤال بـ 0.33333 . انكسرت رقبتي و أنا أطالع بالورقة و كان دقيق . التصحيح للاختبار كان الكتروني يعني ما للدكتور علاقة فيه .\n\nالقريد النهائي:\nأعطي الدكتور A . كلاسه ممتع بالحيل .\n\nالصوت:\n\nصوته واضح . كنت أغلب أيام حضوري أجلس في الصف الثالث أو الثاني . و أسمعه بدون أي مشاكل . لغته الإنجليزية ممتازة زي ما ذكروا الشباب .\n\nإضافات :\n\nدكتور فلّة و حبيب و محترم جداً . يقول للطلاب من بداية الفصل إنه يعطي بونصز . كثير من الطلاب ما استفادوا من هالشغلة . أنا طلعت منه بحول الـ 5% بونص . و بما إن المادة ستاندرد فهذي لحالها قريد .\n\nأضيف أنه يعطي أساينمنتس ممتعه . مثلاً أعطانا الترم هذا أساينمنت تشوف فلمين و تستقي منهم معلومات مرتبطة بالكورس .\n\nأيضاً عطانا أساينمنت أنك تبيع شغلة عن طريق النتّ .\n\nأيضاً جاب لنا Guest speaker عن الأونلاين بزنسز في السعودية … و هو الدكتور مصطفى أحمد صاحب موقع SaleTab .\n\nباختصار … نزل عنده و أنت مغمض لأنك حتستمتع… و شد حيلك شعرة لأنك حتحتاج تذاكر عشان تاخذ قريد .\n\nأنصح فيه و أنت مغمض عيونك و تمشي بالريوس 🤠\n\nهذا تقييمي للدكتور لمادة MIS 215 . الدكتور رهيب و الله يوفقه و يعافيه ع الكورس اللطيف اللي عطانا إياه.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1313660-mis215", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mr-hussam-almulhim/98428/4", "user": "cortex", "ts": 1388679474000, "tid": 98428, "pn": 4}}]}', 1388679474000, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-s.a.l.m.a.n-mis215', 'stk-s.a.l.m.a.n', 'MIS 215', 'doc', '{"docs": [{"id": "stk-dr-f98433", "n": "Dr. Mustafa Eid", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "درست عنده mis 215 و mis 301\n\nالتحضير :\n\nيحضر اول المحاضره\n\nطريقة الشرح :\n\nيقعد على الكرسي , يفتح السلايدز ويقعد يشرح , بتتعجب كيف ان الانسان له القدره ان يتكلم لمدة ساعه وربع بدون توقف\n\nالكويزات :\n\nبسيطه , تقريبا اسبوعية ومن التي بي , اختيارات و t\\f\n\nالمياجر:\n\nكومون\n\nالفاينلات :\n\nكومون\n\nالقريد النهائي:\n\nالدكتور حبيب لكني بعطيه c\n\nالصوت:\n\nواضح نوعا ما\n\nإضافات :\n\nمافيه هومووركات , احيانا تقريبا مره في الاسبوع يسوي كلاس وورك و ديسكشن في الكلاس وعليها درجات\n\nالدكتور ممل في طريقة شرحه , واقصد بممل لدرجة اذا ما الهيت نفسك بشي صدقني بتنام , انا بالنسبة لي كان كلاس 215 عبارة عن فيسبوك وتشييك ايميلات , لكن حاولت اركز في 301\n\nاتمنى بصراحة لو الدكتور يغير من منهجيته في التدريس ويكون اسلوبه اكثر حيوية خصوصا في مواد mis 3xx و mis 4xx\n\nالمدرس ما يظلم احد , حقك بتاخذه كاملا لا زياده ولا نقصان\n\n🙂", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p901330-mis215", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-mustafa-eid/98433/8", "user": "S.a.l.m.a.n", "ts": 1315969100000, "tid": 98433, "pn": 8}}]}', 1315969100000, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user9921-mis215', 'stk-user9921', 'MIS 215', 'doc', '{"docs": [{"id": "stk-dr-f98441", "n": "Dr. Ehab Qahwash", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Mis 215 Term 161\nالتحضير :\nسؤال قصير جماعي ( طالبين أو ثلاثة ) نهاية المحاضرة نحلّه ويحضّر منه\n\nطريقة الشرح : بوربوينت وإذا بغى يوضّح الأفكار يطلع من البوربوينت ويورّينا اياها من النت\n\nالكويزات : عطانا ٧ كويزات حذف منهم أسوأ ٢ ، كلهم MCQs و TF\n\nالمياجر: كومن وتحتاج لحفففظظظ\n\nالفاينلات : كومن\n\nالقريد النهائي: A\n\nالصوت: وااضح\n\nإضافات : الدكتور متعاون ومحاضرته ممتعة ونادراً ما تحس بالملل ، شرحه كأنه واحد من ربعك يسولف معاك", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1466394-mis215", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ehab-qahwash/98441/33", "user": "user9921", "ts": 1484611505000, "tid": 98441, "pn": 33}}]}', 1484611505000, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-jafar_15-mis215', 'stk-jafar_15', 'MIS 215', 'doc', '{"docs": [{"id": "stk-dr-f98441", "n": "Dr. Ehab Qahwash", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MIS 215 - 172\n\nالتحضير :\nعن طريق كلاس الاسايمنت نهاية كل كلاس، اذا ماكان في اسايمنت غالبا مافي تحضير.\n\nطريقة الشرح :\nيفتح سلايدات الكتاب ويبدا يشرح، شرحه جدا ممتاز ومرات يعطيك مصادر خارجية كزيادة معلومات عن الموضوع\n\nالكويزات :\nسهلة جدا، تكون من TB. نظامه مرة خيارات مرة صح وخطا. ويحذف كم كويز\n\nالمياجر:\nكومن\n\nالفاينلات :\nكومن\n\nالصوت:\nواضح\n\nإضافات :\nبونص مافي، لكنه متساهل من ناحية الاسايمنت. قبل كل ميجر يراجع الاشياء المهمة واللي ماكانت واضحة للطلاب.\nباختصار انصح بالدكتور.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1498423-mis215", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ehab-qahwash/98441/37", "user": "Jafar_15", "ts": 1535629353000, "tid": 98441, "pn": 37}}]}', 1535629353000, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-aziiz99-mis215', 'stk-aziiz99', 'MIS 215', 'doc', '{"docs": [{"id": "stk-dr-f98441", "n": "Dr. Ehab Qahwash", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "mis215-172\nالتحضير :\nما يحضر احيانا يوزع أوراق عليها درجات يمديك تخلي اخوياك يحطون اسمك معهم\n\nالكويزات :\nتجي بالحرف من التست بانك\n\nالمياجر:\nكومن\n\nالفاينلات :\nكومن\n\nالقريد النهائي:\nA\nالصوت:\nواضح\n\nإضافات :\nالدكتور حبيب جدا و انصحك تنزل معه بس اذا ما ناسبك وقته عادي فيه غيره كثير كويسين", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1502349-mis215", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ehab-qahwash/98441/38", "user": "aziiz99", "ts": 1542144689000, "tid": 98441, "pn": 38}}]}', 1542144689000, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-_182-mis215', 'stk-_182', 'MIS 215', 'doc', '{"docs": [{"id": "stk-dr-f98441", "n": "Dr. Ehab Qahwash", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MIS215-181\n\nالتحضير: عن طريق نشاط صفّي، اللي كتبوا أسماءهم حاضرين، وإذا ما في نشاط فغالبًا ما يحضّر.\nطريقة الشرح: باوربوينت\nالكويزات: سهلة، خيارات وصح أو خطأ (يحذف أسوأ اثنين)\nالمياجر: موحّد\nالفاينلات: موحّد\nالقريد النهائي: +A\nالصوت: واضح واللغة الإنجليزية ممتازة\nإضافات:\n\n- يحرجك بطيبته، أخلاق عالية ومتفهم للظروف\n- حريص على الطلاب، يحاول يساعدهم قد ما يقدر، بالإضافة إلى تنظيمه ومحاولة توفيره للعديد من الدورات التي تفيد الطلاب في مختلف التخصصات\n- ما يعطي درجات زيادة، والمفروض أنك ما تحتاج لزيادة معه!\n\nأنصح فيه كخيار أول", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1506648-mis215", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ehab-qahwash/98441/39", "user": "_182", "ts": 1551615245000, "tid": 98441, "pn": 39}}]}', 1551615245000, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user10108-mis215', 'stk-user10108', 'MIS 215', 'doc', '{"docs": [{"id": "stk-dr-f98442", "n": "Dr. Saleh Al-Wahaishi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ترم 131 mis 215\nالمدرس كلاسه جدا جدا ممتع ومفيد , طريقة شرحع غير تقليدية ابدا\nويجيب امثلة من عنده للدرس تخليك تفهمه مضبوط\nالبروجكت عنده اعلى واحد جاب 13.5\nحبيب و متعاون , لكنه زعل مننا مرة لأنه تأحر 10 دقايق وكل الفصل مشى وصار يحاسب من بعدها على التأخير:) مع العلم انه قبل هالحركة ما كان يحاسب !! 🤠\nأنصح فييه وبقوة في mis215\nوتراه عطى اب جريد للطلاب واللي ما عنده ولا غياب زوده درجة", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1326757-mis215", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/saleh-al-wahaishi/98442/15", "user": "user10108", "ts": 1391599200000, "tid": 98442, "pn": 15}}]}', 1391599200000, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user10207-mis215', 'stk-user10207', 'MIS 215', 'doc', '{"docs": [{"id": "stk-dr-f98442", "n": "Dr. Saleh Al-Wahaishi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MIS 215 – Term 141\nيحضر أول الكلاس.\nطريقة الشرح: يشرح على السلايدات وتكون مناقشة بينه وبين الطلاب.\nالشرح ممتاز ويوصل المعلومة بشكل رائع.\nالكويزات بسيطة جداً. تكون على شكل إختيارات. ذاكر من الكتاب وخصوصاً التعاريف وإن شاء الله تجيب درجات طيبة.\nالمياجر والفاينل كومن بين كل السكاشن. 30 سؤال إختيارات و3 أسئلة كتابية \"\"Case Study من كل شبتر سؤال.\nطبعاً الكويزات على كل الشباتر. بعد ما تخلص الشبتر، الأسبوع الجاي عليه كويز.\nيحذف أسوء كويز لك من بين الـ 11 كويز.\nخلال السمستر يطلب من الطلاب assignments وهوموركات. الي يبدع بهذه الأشياء يعطيه بونص.\nبعض الأحيان يطلب من الطلاب يسوون مجموعة بالكلاس ويحلون الأوراق الي يعطيهم.\nتصحيحه ممتاز جداً ويساعد الطلاب في الميجر والبروجكت (عكس كلام الطلاب هنا في الموضوع). لكن أنت حاول تهتم.\nصوته واضح. لغته الإنجليزية ممتازة. بعض الأحيان يتكلم عربي لتوضيح الأشياء والمصطلحات.\nيستعمل البلاكبورد والإيميل بشكل رائع!\nيرصد درجاتك من أول الترم لآخر في البلاكبورد بعد كل كويز أو ميجر أو اي assignment مباشرة.\nأفضل مدرس رأيته يستخدم البلاكبورد حتى الآن.\nيعطي بونصات كثير.\nالي ماعنده غياب بونص. بعض المرات يسأل والي يجاوب يأخذ بونص. وإذا بدعت بالهوموركات يعطيك بونص.\nدمه خفيف ويحب يضحك الطلاب بكل كلاس.\nالكلاس ممتع وما تمل منه.\nأخلاقه رائعة ومحترم. أنصح به.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1421179-mis215", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/saleh-al-wahaishi/98442/17", "user": "user10207", "ts": 1421874726000, "tid": 98442, "pn": 17}}]}', 1421874726000, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abu_taki-mis215', 'stk-abu_taki', 'MIS 215', 'doc', '{"docs": [{"id": "stk-dr-f98442", "n": "Dr. Saleh Al-Wahaishi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MIS 215 – Term 151\n\nالدكتور صالح طيب وخلوق … محبوب من الطلاب\n\nممتاز كشرح … معظم الوقت يتكلم بالعربي ويوصل المعلومة بشكل ممتاز باستخدام أمثلة قريبة من الواقع\n\nيعطي بونص درجة واحدة للي ماعندهم أي غياب\n\nالكويزات عنده سهلة … يختبرك في كويز كل تشابتر … 10 اسئلة اختيارية ( أحيانا سؤال واحد اضافي ) والاسئلة من التست بانك\n\nالمياجر كومن … 20 فقرة اختيارية … 3 اسئلة مقالية …\n\nالفاينل 60 فقرة اختيارية … الاسئلة الاختيارية في الكويزات والمياجر والفاينل 90% من التست بانك ان لم يكن اكثر\n\nتصحيح الدكتور جيد جدا ومتساهل بالحد المعقول ( بالنسبة للاسئلة المقالية )\n\nالقريد النهائي B+", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1437599-mis215", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/saleh-al-wahaishi/98442/21", "user": "Abu_Taki", "ts": 1451600648000, "tid": 98442, "pn": 21}}]}', 1451600648000, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-waleedx11-mis215', 'stk-waleedx11', 'MIS 215', 'doc', '{"docs": [{"id": "stk-dr-f98442", "n": "Dr. Saleh Al-Wahaishi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MIS215 TERM 161\n\nالتحضير : ينادي بالأسماء لما يبدأ وقت الكلاس عن طريق ورقة مكتوبة فيها أساميهم … وزاد درجة للي ماغاب ولا غياب في نهاية السمستر.\n\nطريقة الشرح : رهيب رهيب رهيب … ماشاء الله صدقًا كلاس الدكتور صالح لا يمل منه وما تحس بعض المرات بانتهاء الوقت من طريقة الشرح الجيدة.\n\nالكويزات : 9 كويزات … الكويز عبارة عن اختيار من متعدد وسؤالين مقاليين بس في الكويزات الأخيرة صارت اختيار من متعدد فقط … وحذف أسوأ كويزين في نهاية السمستر على ما أظن.\n\nالمياجر: ميجرين كل واحد عليه ٢٠٪ من المادة وكانت MCQ وسؤالين مقاليين عليهم وزن كبير من الميجر. غالبًا حيفيدك التست بانك ولكنه ليس الكل في الكل والدليل الفاينل.\n\nالفاينلات : عليه ٢٠٪ كذلك وكان MCQ و T/F .\n\nالقريد النهائي: الدكتور أعطيه A نظرا لشرحه الرائع وتمكنه من المادة.\n\nالصوت: واضح جدًا ولغته الانجليزية ماشاء الله جبارة.\n\nطبعا في 3 بروجكتات( تختار بكيفك جماعية أو فردية ) في المادة كل وحدة عليها 5% ، وكمان عدد من الكلاس ووركات تحلونه كمجموعة في الكلاس عليها 15% وكان الدكتور يبذل أقصى ما بوسعه علشان يساعد الطلاب والحمدلله.\n\nإضافات : الدكتور صالح ماشاء الله عليه حبوب وخلوق و تعجبني طريقة طرحه للمواضيع ونقاشه مع الطلاب في الكلاس بس فيه السلبية الوحيدة إنه يكرفك طول السمستر بلا توقف يعني تقريبا كل كلاس فيه يا كويز أو كلاس وورك كحد أقصى فيبيلك تتابع معه أول بأول علشان تطلع معه بقريد كويس ، خله خيارك الثاني مباشرة بعد إيهاب قحوش في حال تواجده في الريجسترار.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1466877-mis215", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/saleh-al-wahaishi/98442/23", "user": "waleedx11", "ts": 1485214450000, "tid": 98442, "pn": 23}}]}', 1485214450000, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user12072-mis215', 'stk-user12072', 'MIS 215', 'doc', '{"docs": [{"id": "stk-dr-f180467", "n": "Dr. Jongtae Yu", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "mis 215-online(202)\nالتحضير : مافي تحضير, بعض الاحيان يسأل بالاسم\nطريقة الشرح : يشرح من السلايدات يقرأ ويوضح\nالكويزات : 10 اسئله خيارات وسؤال تعريف وتكتب اسم المصطلح, لكل شابتر اخذنا كويز.الكويزات مو حيل سهله ولا حيل صعبه, يحتاج تذاكر لها\nالمياجر:كومن mcq و صح وخطأ الصعوبه متسوطه الى سهله\nالفاينلات : نفس المياجر\nالقريد النهائي: اعطي الدكتور B+\nالبروجكت: عليه 15 وتكلم شركه وتفهم ال it في الشركه\nالهوموركات: الواجبات في الماده كثيييييييييير راح تسون قروب للبروجكت في البدايه وبعدين بيكون هو للواجبات لانه بعض الواجبات جماعي وبعضها فردي,اذا فريقك مو متعاون راح تاكلها لحالك\nالصوت: ;كوري لكن ينفهم\nإضافات : الماده مادة حفظ ثم حفظ ثم حفظ, كلها مسطلحات ومفاهيم تعبتر مادة قريد للي قوي في الحفظ", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1530021-mis215", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/jongtae-yu/180467/5", "user": "user12072", "ts": 1621532957000, "tid": 180467, "pn": 5}}]}', 1621532957000, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-makkahboy-mis215', 'stk-makkahboy', 'MIS 215', 'doc', '{"docs": [{"id": "stk-dr-f180469", "n": "Dr. Mousa Al-Bashrawi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "طيب انا ما اعرف اولا كيف الدكتور محطوط في قسم الاقتصاد والمالية\nعموما، أنا درست عنده\nMIS215 - Term 181\n\nالتحضير: الأصل أنه ما يحضر لكن كل كلاس تقريبا فيه نشاط للمجموعات\nالمجموعات يقسمها في بداية السمستر. وكل كلاس يكون فيه نشاط المجموعة تعمل له سبميت عن طريق البلاكبورد ويطلب منهم أنهم يسجلو اسم الشخص الغائب في مجموعتهم\nاحنا كنا نسحب ما نسجل، اللي يغيب نغطي عليه. بعدين بدأ يعرف الهرجة وكان يشدد. لكن عموما الدكتور طيب ومتساهل.\nأما تحضير بالأسماء ف مافي.\n\nطريقة الشرح: يفتح السلايدات ويتكلم. صوته راخي.\nالكويزات: TB ، ولو مذاكر الكتاب تجيبها وأنت مغمض. طبعا الدكتور يختبر 7 كويزات ويأخذ أفضل 5\nالمياجر: كومون. الميجر الأول كان Multiple choice و جزئية Written عن ال Excel. الاختيارات كانت TB والريتن جدا سهل إذا مذاكر بتجيبها.\nالميجر الثاني نفس الأول Multiple choice من TB و جزئية الWritten عن Access وسهلة برضو.\n\nالفاينلات: كومون ماكانت كلها من الTB لكنها كانت سهلة.\n\nالقريد النهائي +A وبكل جدارة!!! سجل معه وانت مغمض.\n\nالصوت: راخي بالمجمل لكنه مسموع\n\nإضافات: الدكتور حبييييب جدا صراحة ومايتكلم على التأخير أبدا وخذ راحتك بالكلاس. مايكلمك إلا لو سببت إزعاج\nبنهاية بعض المحاضرات يسأل أسئلة من الـTB ويعطي عليها بونص. حريص يعطي الكل بونص الله يعطيه العافية\nالدكتور بططططل وحبييييب جدا.\nالمادة فيها 2 Projects\nوكلهم سهالات جدا والله بس تحتاج تعاون بسيط من شباب المجموعة.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1504272-mis215", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mousa-al-bashrawi/180469/2", "user": "makkahboy", "ts": 1546184550000, "tid": 180469, "pn": 2}}]}', 1546184550000, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
